import type { Command } from 'commander';

interface AccessibleTeam {
  id: string;
  name: string;
  slug: string;
  organizationId: string;
  createdAt: string;
  updatedAt: string;
}

/**
 * Finds a team within a list by identifier, matching by id first, then by
 * case-insensitive display name, then by slug (in that priority order).
 */
function findTeamByIdentifier(
  teams: AccessibleTeam[],
  identifier: string,
): AccessibleTeam | undefined {
  return (
    teams.find((t) => t.id === identifier) ||
    teams.find((t) => t.name.toLowerCase() === identifier.toLowerCase()) ||
    teams.find((t) => t.slug === identifier)
  );
}

/** Returns the team with the earliest createdAt date (the oldest team). */
function oldestTeam(teams: AccessibleTeam[]): AccessibleTeam {
  return [...teams].sort(
    (a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime(),
