/**
 * Resolves the organization and the pool of teams to consider during login, and
 * persists the resolved organization and team cache. Throws if an explicit --org
 * has no accessible teams.
 * @param allTeams - All teams accessible to the user.
 * @param fallbackOrgId - The default organization id from the token validation response.
 * @param orgFlag - The --org flag value, if provided.
 * @param teamFlag - The --team flag value, if provided.
 */
function resolveOrgAndTeamPool(
  allTeams: AccessibleTeam[],
  fallbackOrgId: string,
  orgFlag?: string,
  teamFlag?: string,
): { resolvedOrgId: string; teamPool: AccessibleTeam[] } {
  let resolvedOrgId: string;
  let teamPool: AccessibleTeam[];

  if (orgFlag) {
    // --org specified: restrict to teams belonging to that organization.
    const filtered = allTeams.filter((t) => t.organizationId === orgFlag);
    if (filtered.length === 0) {
      const availableOrgIds = [fallbackOrgId, ...allTeams.map((t) => t.organizationId)].filter(
        (id, index, arr) => arr.indexOf(id) === index,
      );
      throw new Error(
        `Organization '${orgFlag}' not found in your accessible teams. Available organizations: ${availableOrgIds.join(', ')}`,
      );
    }
    resolvedOrgId = orgFlag;
    teamPool = filtered;
  } else if (teamFlag) {
    // --team without --org: find the matching team across all organizations.
    const match = findTeamByIdentifier(allTeams, teamFlag);
    if (!match) {
      throw new Error(
        `Team '${teamFlag}' not found. Available teams: ${allTeams.map((t) => t.name).join(', ')}`,
      );
    }
    resolvedOrgId = match.organizationId;
    teamPool = allTeams.filter((t) => t.organizationId === resolvedOrgId);
  } else {
    // No flags: prefer the default organization from the token validation response,
    // otherwise fall back to the organization containing the oldest-created team.
    const defaultOrgTeams = allTeams.filter((t) => t.organizationId === fallbackOrgId);
    if (defaultOrgTeams.length > 0) {
      resolvedOrgId = fallbackOrgId;
      teamPool = defaultOrgTeams;
    } else if (allTeams.length > 0) {
      resolvedOrgId = oldestTeam(allTeams).organizationId;
      teamPool = allTeams.filter((t) => t.organizationId === resolvedOrgId);
    } else {
      resolvedOrgId = fallbackOrgId;
      teamPool = [];
    }
  }

  cloudConfig.setCurrentOrganization(resolvedOrgId);
  cloudConfig.cacheTeams(teamPool, resolvedOrgId);
  return { resolvedOrgId, teamPool };
}

/**
 * Selects a team from the resolved team pool. Uses an explicit identifier when
 * provided, otherwise auto-selects a single team, prompts interactively, or falls
 * back to the oldest team (non-interactive or cancelled selection).
 * @param teamPool - The teams available for selection.
 * @param teamFlag - The --team flag value, if provided.
 */
async function selectTeamFromPool(
  teamPool: AccessibleTeam[],
  teamFlag?: string,
): Promise<{ selectedTeam?: AccessibleTeam; teamIsDefault: boolean }> {
  if (teamFlag) {
    // Explicit team identifier: resolve within the team pool.
    const selectedTeam = findTeamByIdentifier(teamPool, teamFlag);
    if (!selectedTeam) {
      throw new Error(
        `Team '${teamFlag}' not found. Available teams: ${teamPool.map((t) => t.name).join(', ')}`,
      );
    }
    return { selectedTeam, teamIsDefault: false };
  }

  if (teamPool.length === 1) {
    return { selectedTeam: teamPool[0], teamIsDefault: false };
  }

  if (teamPool.length === 0) {
    return { selectedTeam: undefined, teamIsDefault: false };
  }

  if (isNonInteractive()) {
    // Non-interactive: automatically select the oldest team.
    const selectedTeam = oldestTeam(teamPool);
    logger.warn(
      chalk.yellow(
        `\n⚠️  You have access to ${teamPool.length} teams. Using '${selectedTeam.name}'.`,
      ),
    );
    logger.info(chalk.dim(`   Use --team flag to specify: promptfoo auth login --team <name>`));
    return { selectedTeam, teamIsDefault: false };
  }

  // Interactive: prompt the user to select a team.
  logger.info('');
  try {
    const answer = await select({
      message: 'Select a team to use:',
      choices: teamPool.map((team) => ({
        name: team.name,
        value: team.id,
        description: team.slug,
      })),
    });
    return { selectedTeam: teamPool.find((t) => t.id === answer), teamIsDefault: false };
  } catch {
    // User cancelled (Ctrl+C): fall back to the oldest team.
    return { selectedTeam: oldestTeam(teamPool), teamIsDefault: true };
  }
}

